{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Activity log alert contains a contradictory resource filter",
      "resource": "azurerm_monitor_activity_log_alert.negative1",
      "severity": "MEDIUM",
      "explanation": "The alert filters for network security group deletion events while also requiring the affected resource to be a storage account. These conditions cannot match the same event, making the security alert ineffective."
    }
  ],
  "patched_code": "resource "azurerm_monitor_activity_log_alert" "negative1" {
  name                = "example-activitylogalert"
  resource_group_name = azurerm_resource_group.example.name
  location            = azurerm_resource_group.example.location
  scopes              = [azurerm_resource_group.example.id]
  description         = "Negative sample"

  criteria {
    operation_name = "Microsoft.Network/networkSecurityGroups/delete"
    category       = "Administrative"
  }

  action {
    action_group_id = azurerm_monitor_action_group.main.id

    webhook_properties = {
      from = "terraform"
    }
  }
}
",
  "fix_summary": "Removed the contradictory storage account resource filter so the alert can detect network security group deletion events throughout the configured resource group scope."
}
